 ~Impl(){if(current==this)current=nullptr;}
 void authority(){const auto v=session.summary();need(current==this&&thread==GetCurrentThreadId()&&&session.runtime()==&r&&v[1]&&!v[3]&&!v[4]&&session.live_handle(),"Current same-thread unpoisoned constructor Session");}
