 unsigned word(unsigned a){return r.memory().load<unsigned>({a});}
 const literal::Instruction&instruction(unsigned pc){need(active&&pc!=0x56fea0,"Cold recursive frontier is retained but unadmitted");const auto*row=literal::instruction(pc);need(row,"Complete physically prepared constructor source PC");std::array<std::byte,16>b{};r.memory().read({pc},std::span(b.data(),row->size));for(unsigned n=0;n<row->size;++n)need(std::to_integer<unsigned>(b[n])==row->bytes[n],"Whole physical constructor instruction preimage");return*row;}
 void fs(unsigned pc,unsigned value,bool writing){unsigned kind{};const auto head=word(r.fs_base().value);if(writing){if(!FS_frames.empty()&&value==FS_frames.back().previous){const auto f=FS_frames.back();need(head==f.frame&&word(f.frame)==f.previous&&word(f.frame+4)==f.handler&&word(f.frame+8)==f.scope,"Whole active constructor FS frame and predecessor restoration");FS_frames.pop_back();kind=2;}else{need(value==s.gpr.rsp.dword&&value>=r.stack_low().value&&std::uint64_t(value)+12<=r.stack_top().value&&FS_frames.size()<32&&word(value)==head,"Literal constructor FS installation from current full caller frame");FS_frames.push_back({value,head,word(value+4),word(value+8),++FS_invocation});kind=1;}}else need(value==head,"Actual complete constructor FS head operand");FS_events.push_back({root,pc,unsigned(writing),head,value,kind,unsigned(FS_frames.size()),FS_invocation,0,0,0,0});}
 std::uint64_t read(unsigned a,unsigned n){authority();const auto pc=s.gpr.rip.dword;const auto&row=instruction(pc);need(n&&n<=4&&accesses.size()<300000,"Finite literal constructor read width/budget");std::array<std::byte,4>b{};r.memory().read({a},std::span(b.data(),n));std::uint64_t v{};std::memcpy(&v,b.data(),n);session.constructor_owner_read(s,root,pc,a,n,v);accesses.push_back({pc,a,v,n,0});if(a==r.fs_base().value){need(n==4,"Whole source FS DWORD");fs(pc,unsigned(v),false);}if(pc==0x5ac11e){need(n==4&&a==0x5bb52c&&v==literal::onexit_raw,"Whole owning raw CRT onexit import");return 0x78004a36;}if(row.ret)last_return=pc;return v;}
