extern "C" void mw34_constructor_invoke_guarded(void*p)noexcept{auto&t=*static_cast<Task*>(p);try{if(t.borrowed)t.owner->invoke(t.root);else t.owner->r.invoke({t.root});}catch(...){const auto first=std::current_exception();t.owner->session.abort_constructor(t.owner->s,t.root);t.owner->active=false;t.owner->failed=true;t.exception=first;}}
extern "C" std::uint8_t mw34_constructor_game_read8(void*p,unsigned a){return std::uint8_t(owner(p).read(a,1));}extern "C" std::uint16_t mw34_constructor_game_read16(void*p,unsigned a){return std::uint16_t(owner(p).read(a,2));}extern "C" unsigned mw34_constructor_game_read32(void*p,unsigned a){return unsigned(owner(p).read(a,4));}
extern "C" void*mw34_constructor_game_write8(void*p,unsigned a,std::uint8_t v){owner(p).write(a,v,1);return p;}extern "C" void*mw34_constructor_game_write16(void*p,unsigned a,std::uint16_t v){owner(p).write(a,v,2);return p;}extern "C" void*mw34_constructor_game_write32(void*p,unsigned a,unsigned v){owner(p).write(a,v,4);return p;}
extern "C" void*mw34_constructor_game_call(State*s,unsigned a,void*p){auto&c=owner(p);need(&c.s==s,"Actual current constructor State");return c.dispatch(a,false);}extern "C" void*mw34_constructor_game_jump(State*s,unsigned a,void*p){auto&c=owner(p);need(&c.s==s,"Actual current constructor State");return c.dispatch(a,true);}extern "C" void*mw34_constructor_game_missing(State*s,unsigned a,void*p){return mw34_constructor_game_jump(s,a,p);}extern "C" void*mw34_constructor_game_return(State*s,unsigned a,void*p){auto&c=owner(p);need(&c.s==s,"Actual current constructor State");c.returned(a);return p;}
